begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.cid(text) returns uuid language sql immutable as $$select md5('approved-credit-'||$1)::uuid$$;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select pg_temp.cid(u),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',u||'@approved.example.test','','{}','{}',now(),now() from unnest(array['owner','other','staff'])u;
insert into organizations(id,name,slug,industry) values(pg_temp.cid('org'),'Approved','approved-credits','salon'),(pg_temp.cid('other'),'Other','approved-other','pet_care');
insert into organization_memberships(organization_id,user_id,role) values(pg_temp.cid('org'),pg_temp.cid('owner'),'owner'),(pg_temp.cid('org'),pg_temp.cid('staff'),'advisor'),(pg_temp.cid('other'),pg_temp.cid('other'),'owner');
select is((select monthly_credits from plans where id='free'),0,'Free monthly allowance zero');
select is((select one_time_credits from plans where id='free'),100,'Free one-time allowance 100');
select is((select monthly_credits from plans where id='starter'),100,'Starter configured 100');
select is((select monthly_credits from plans where id='business'),300,'Growth configured 300');
select is((select monthly_credits from plans where id='pro'),750,'Pro configured 750');
select ensure_credit_period(pg_temp.cid('org'));
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'remaining')::integer,100,'Free grant once');
select ok(credit_balance_data(pg_temp.cid('org'))->>'nextRefresh' is null,'Free has no renewal');
insert into organization_subscriptions(organization_id,plan_id,provider,status,current_period_start,current_period_end)
values(pg_temp.cid('org'),'starter','manual','active',now()-interval '1 day',now()+interval '29 days');
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,100,'Starter grant and retry');
update organization_subscriptions set plan_id='business' where organization_id=pg_temp.cid('org');
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,300,'Growth upgrade adds 200 exactly');
select is((select max(allowance) from organization_credit_grants where organization_id=pg_temp.cid('org') and credit_class='plan'),200,'upgrade difference recorded separately');
update organization_subscriptions set plan_id='pro' where organization_id=pg_temp.cid('org');
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,750,'Pro upgrade adds 450');
update organization_subscriptions set plan_id='starter' where organization_id=pg_temp.cid('org');
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyAllowance')::integer,750,'downgrade keeps current allowance');
select ok((select bool_and(subscription_key is not null) from organization_credit_grants where credit_class='plan'),'included identity contains subscription');
update organization_credit_grants set period_start=now()-interval '2 months',period_end=now()-interval '1 month',expires_at=now()-interval '1 month',grant_key='expired:'||id where credit_class='plan';
select ensure_credit_period(pg_temp.cid('org'));
select is((credit_balance_data(pg_temp.cid('org'))->>'monthlyRemaining')::integer,100,'new period receives downgraded allowance without rollover');
select is((select sum(amount) from organization_credit_ledger where transaction_type='EXPIRATION'),-750::bigint,'unused included credits expire audibly');
select is((credit_balance_data(pg_temp.cid('org'))->>'oneTimeRemaining')::integer,100,'monthly refresh preserves one-time bucket');
update organization_subscriptions set status='cancelled' where organization_id=pg_temp.cid('org');
select ensure_credit_period(pg_temp.cid('org'));
select is((select count(*) from organization_credit_grants where credit_class='one_time' and organization_id=pg_temp.cid('org')),1::bigint,'cancellation never regrants Free');
select is(plan_entitlements(pg_temp.cid('org'))->>'planId','free','cancellation uses Free entitlements');
select ok(credit_balance_data(pg_temp.cid('org'))->>'nextRefresh' is null,'cancelled account does not promise refresh');
select is((select credit_cost from credit_operation_registry where operation_key='sms_notification'),1,'SMS segment price one');
select ok((select bool_and(credit_cost=0) from credit_operation_registry where operation_key in('transactional_email','advanced_report','csv_export','image_upload')),'email reports exports and images have zero cost');
select ok((select credit_cost=5 and not enabled from credit_operation_registry where operation_key='ai_insight'),'AI insight configured but disabled');
select ok((select credit_cost is null and not enabled from credit_operation_registry where operation_key='ai_advanced_operation'),'advanced AI unconfigured');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('owner'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select * from organization_credit_ledger$$,'42501',null,'ledger cannot be enumerated directly');
select throws_ok($$select get_credit_usage(pg_temp.cid('other'))$$,'42501',null,'foreign ledger hidden');
with attempted as(update plans set monthly_credits=9000 where id='free' returning id) select is((select count(*) from attempted),0::bigint,'RLS prevents owner allowance changes');
select throws_ok($$select reserve_credit_operation(pg_temp.cid('other'),'sms_notification',gen_random_uuid(),'forged','{"segments":1}')$$,'42501',null,'browser cannot consume foreign credits or supply a cost');
with attempted as(update organization_subscriptions set current_period_end=now()+interval '10 years' returning organization_id) select is((select count(*) from attempted),0::bigint,'RLS prevents browser billing period changes');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('staff'),'role','authenticated')::text,true);
set local role authenticated;
select throws_ok($$select get_credit_usage(pg_temp.cid('org'))$$,'42501',null,'ordinary staff cannot view billing');
select throws_ok($$select get_credit_notices(pg_temp.cid('org'))$$,'42501',null,'ordinary staff cannot view credit notices');
reset role;
select is((select period_start from credit_period_window('2026-01-31 12:00Z','2027-01-31 12:00Z','2026-02-28 12:00Z')),'2026-02-28 12:00Z'::timestamptz,'annual Jan31 anchor refreshes February28');
select is((select period_end from credit_period_window('2026-01-31 12:00Z','2027-01-31 12:00Z','2026-02-28 12:00Z')),'2026-03-31 12:00Z'::timestamptz,'clamped month never drifts original anniversary');
select ensure_credit_period(pg_temp.cid('other'));
insert into organization_credit_ledger(organization_id,grant_id,transaction_type,amount,reason_code,idempotency_key) select organization_id,id,'ADJUSTMENT',-80,'synthetic_threshold','low' from organization_credit_grants where organization_id=pg_temp.cid('other') and credit_class='one_time';
select notify_credit_threshold(pg_temp.cid('other'));select notify_credit_threshold(pg_temp.cid('other'));
select is((select count(*) from organization_in_app_notices where organization_id=pg_temp.cid('other') and kind='LOW'),1::bigint,'LOW deduplicates across repeated calls');
insert into organization_credit_ledger(organization_id,grant_id,transaction_type,amount,reason_code,idempotency_key) select organization_id,id,'ADJUSTMENT',-10,'synthetic_threshold','critical' from organization_credit_grants where organization_id=pg_temp.cid('other') and credit_class='one_time';
select notify_credit_threshold(pg_temp.cid('other'));select notify_credit_threshold(pg_temp.cid('other'));
select is((select count(*) from organization_in_app_notices where organization_id=pg_temp.cid('other') and kind='CRITICAL'),1::bigint,'CRITICAL deduplicates');
insert into organization_credit_ledger(organization_id,grant_id,transaction_type,amount,reason_code,idempotency_key) select organization_id,id,'ADJUSTMENT',-10,'synthetic_threshold','empty' from organization_credit_grants where organization_id=pg_temp.cid('other') and credit_class='one_time';
select notify_credit_threshold(pg_temp.cid('other'));select notify_credit_threshold(pg_temp.cid('other'));
select is((select count(*) from organization_in_app_notices where organization_id=pg_temp.cid('other') and kind='EMPTY'),1::bigint,'EMPTY deduplicates');
insert into organization_credit_ledger(organization_id,grant_id,transaction_type,amount,reason_code,idempotency_key) select organization_id,id,'ADJUSTMENT',100,'synthetic_threshold','restore' from organization_credit_grants where organization_id=pg_temp.cid('other') and credit_class='one_time';
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cid('other'),'role','authenticated')::text,true);
set local role authenticated;
select is(jsonb_array_length(get_credit_notices(pg_temp.cid('other'))),0,'restored balance hides old notices');
reset role;
select * from finish();
rollback;
